function appendSupplierDocuments(supplierId){if(!modalBody||document.getElementById('v1092SupplierDocuments'))return;const {sup,inv}=states(),orders=A(sup?.purchaseRequests).filter(x=>x.supplierId===supplierId&&!isArchived(x)).slice().sort((a,b)=>S(b.date).localeCompare(S(a.date))).slice(0,10),invoices=A(inv?.purchaseInvoices).filter(x=>x.supplierId===supplierId&&!isArchived(x)).slice().sort((a,b)=>S(b.date).localeCompare(S(a.date))).slice(0,10);modalBody.insertAdjacentHTML('beforeend',`<div id="v1092SupplierDocuments" class="card"><div class="section-head"><h3>سفارش‌ها و فاکتورهای خرید</h3><a class="btn btn-sm" href="suppliers.html?tab=documents">مشاهده همه</a></div><div class="grid grid-2"><div><b>آخرین سفارش‌ها</b>${orders.map(x=>`<div class="hint">${E(orderNumber(x))} — ${E(x.date)} — ${E(docStatusLabel(x,'order'))}</div>`).join('')||'<div class="empty">سفارشی ثبت نشده است.</div>'}</div><div><b>آخرین فاکتورها</b>${invoices.map(x=>`<div class="hint">${E(x.invoiceNumber||x.number)} — ${E(x.date)} — ${E(docStatusLabel(x,'invoice'))} — ${M(invoiceTotal(x))}</div>`).join('')||'<div class="empty">فاکتوری ثبت نشده است.</div>'}</div></div></div>`)}
