function invoiceTotal(x){if(N(x?.totalToman)>0)return N(x.totalToman);return Math.max(0,A(x?.lines).reduce((a,l)=>a+N(l.lineTotalToman||N(l.purchaseQuantity||l.quantity)*N(l.unitPrice)-N(l.discountToman)),0)-N(x?.discount)+N(x?.taxToman)+N(x?.extraCostToman))}
function supplierAccount(inv,id){const invoices=A(inv?.purchaseInvoices).filter(x=>invoiceIsFinal(x)&&x.supplierId===id),payments=A(inv?.supplierPayments).filter(x=>x.status!=='void'&&x.supplierId===id),purchases=invoices.reduce((a,x)=>a+invoiceTotal(x),0),paid=invoices.reduce((a,x)=>a+N(x.paidAmount),0)+payments.reduce((a,x)=>a+N(x.amount),0);return{invoices,payments,purchases,paid,balance:purchases-paid}}
