function procurementMetrics(){const {sup,pr,inv}=states();if(!sup||!pr||!inv)return null;const suppliers=A(sup.suppliers).filter(x=>!isArchived(x)),catalog=A(pr.ingredients).filter(x=>!isArchived(x)),supplierCodes=new Set(suppliers.map(x=>S(x.code))),catalogIds=new Set(catalog.map(x=>x.id)),catalogCodes=new Set(catalog.map(x=>S(x.code))),relations=A(sup.supplierItems).filter(r=>!isArchived(r)&&S(r.status)!=='غیرفعال'&&supplierCodes.has(S(r.supplierCode))&&(catalogIds.has(r.ingredientId)||catalogCodes.has(S(r.itemCode)))),accounts=suppliers.map(s=>({s,a:supplierAccount(inv,s.id)})),debt=accounts.reduce((a,x)=>a+Math.max(0,x.a.balance),0),positions=catalog.filter(i=>S(i.status)!=='غیرفعال').map(i=>({i,p:currentPosition(i)})),lastValue=positions.reduce((a,x)=>a+Math.max(0,N(x.p.current??x.p.quantity))*N(x.p.unitCost),0);return{suppliers,catalog,relations,accounts,debt,lastValue}}
